const list = document.querySelector('#caseList');
const detail = document.querySelector('#detail');
const home = document.querySelector('#home');
let filter = 'todos';
function card(c){return `<article class="case-card" tabindex="0" role="link" data-case="${c.key}"><div class="card-top"><span class="tag">${countryNames[c.country]||'OUTROS PAÍSES'} · ${c.year}</span><span class="case-id">DOSSIÊ ${c.id}</span></div><h3>${c.title}</h3><p>${c.summary}</p><div class="card-bottom"><span>${c.place.toUpperCase()}</span><b>↗</b></div></article>`}
function renderList(){const q=document.querySelector('#searchInput').value.trim().toLocaleLowerCase('pt-BR');const shown=cases.filter(c=>(filter==='todos'||(filter==='outros'?!['eua','brasil'].includes(c.country):c.country===filter))&&`${c.title} ${c.place} ${c.summary} ${c.year}`.toLocaleLowerCase('pt-BR').includes(q));list.innerHTML=shown.length?shown.map(card).join(''):'<p class="empty">Nenhum dossiê encontrado.</p>';document.querySelector('#caseCount').textContent=`${shown.length} DOSSIÊ${shown.length===1?'':'S'}`;}
function openCase(key){const c=cases.find(x=>x.key===key);if(!c)return;home.hidden=true;detail.hidden=false;const videoBlock=c.video?`<div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${c.video}" title="${c.videoTitle}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe></div><a class="video-link" href="https://www.youtube.com/watch?v=${c.video}" target="_blank" rel="noopener noreferrer">Abrir este vídeo no YouTube ↗</a><p class="media-note">Vídeo relacionado ao caso; não é filmagem da suposta abdução. A reprodução depende da conexão e disponibilidade do YouTube.</p>`:`<p>Não localizamos uma gravação original confiável para este caso. Você pode consultar vídeos relacionados abaixo; os resultados incluem análises e reconstituições.</p><a class="video-link" href="${c.videoSearch}" target="_blank" rel="noopener noreferrer">Buscar vídeos deste caso no YouTube ↗</a>`;detail.innerHTML=`<button class="back" id="backToList">← VOLTAR AO ARQUIVO</button><header class="detail-head"><div><p class="eyebrow">DOSSIÊ ${c.id} · ${c.country==='brasil'?'CASO BRASILEIRO':c.country==='eua'?'CASO DOS ESTADOS UNIDOS':'RELATO INTERNACIONAL'}</p><h1>${c.title}</h1><p class="detail-intro">${c.summary}</p><div class="detail-meta"><span>${c.place}</span><span>${c.year}</span></div></div><div class="detail-status">RELATO NÃO COMPROVADO</div></header><figure class="detail-cover"><img src="${c.gallery[0].src}" alt="${c.gallery[0].alt}"/><figcaption>${c.gallery[0].caption}</figcaption></figure><div class="detail-content"><article class="story">${c.sections.map(([h,...paras])=>`<section><p class="detail-label eyebrow">${h.startsWith('🧠')?'ANÁLISE CRÍTICA':h.startsWith('🎬')?'REPERCUSSÃO CULTURAL':h.startsWith('⭐')?'O MAPA ESTELAR':h.startsWith('👽')?'O RELATO':h.startsWith('😨')?'O MOMENTO':h.startsWith('⏰')?'A CRONOLOGIA':h.startsWith('🛸')?'SESSÕES DE HIPNOSE':h.startsWith('🔬')?'LEMBRANÇAS SOB HIPNOSE':'DETALHES DO CASO'}</p><h2>${h}</h2>${paras.map(p=>`<p>${p}</p>`).join('')}</section>`).join('')}<section class="video-section"><p class="detail-label eyebrow">VÍDEOS RELACIONADOS</p><h2>${c.videoTitle}</h2>${videoBlock}</section><section class="gallery-inline"><p class="detail-label eyebrow">FOTOS E ILUSTRAÇÕES</p><h2>Imagens deste caso</h2><div class="gallery-grid">${c.gallery.slice(1).map(i=>`<figure><img src="${i.src}" alt="${i.alt}" loading="lazy" onerror="this.closest('figure').classList.add('image-error')"/><figcaption>${i.caption}</figcaption></figure>`).join('')}</div></section><section><h2>Fontes e arquivos</h2><p>As referências documentam relatos e investigações; sua existência não comprova uma causa extraterrestre.</p><div class="source-box"><p class="source-title">REFERÊNCIAS COMPLEMENTARES</p>${c.sources.map(([label,url,kind])=>`<a class="source-link" href="${url}" target="_blank" rel="noopener noreferrer">${label}<span>${kind} ↗</span></a>`).join('')}</div></section></article></div>`;document.querySelector('#backToList').addEventListener('click',()=>{location.hash='inicio';});window.scrollTo(0,0);}
document.querySelector('#searchInput').addEventListener('input',renderList);
document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelector('.filter.active').classList.remove('active');b.classList.add('active');filter=b.dataset.filter;renderList();}));
list.addEventListener('click',e=>{const c=e.target.closest('[data-case]');if(c)location.hash=c.dataset.case;});list.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-case]')){e.preventDefault();location.hash=e.target.dataset.case;}});
function route(){const key=location.hash.slice(1);if(key&&key!=='inicio'){openCase(key);}else{detail.hidden=true;home.hidden=false;window.scrollTo(0,0);}}
window.addEventListener('hashchange',route);renderList();route();
